## Code Example

```javascript
function maxLWithSumAtMost(A, T) {
  const n = A.length;
  const ok = (L) => {
    let sum = 0;
    for (let i = 0; i < L; i++) sum += A[i];
    if (sum <= T) return true;
    for (let i = L; i < n; i++) {
      sum += A[i] - A[i - L];
      if (sum <= T) return true;
    }
    return false;
  };
  let lo = 1, hi = n, ans = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (ok(mid)) { ans = mid; lo = mid + 1; } else { hi = mid - 1; }
  }
  return ans;
}
```

